import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
const NONPRINT = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
export function nodeIsPrintable(cp) {
  if (cp === 0x20) return true;
  return !NONPRINT.test(String.fromCodePoint(cp));
}
export function pyReprBody(cps, printableFn) {
  // returns repr including quotes, mimicking CPython unicode_repr
  const hasS = cps.includes(0x27), hasD = cps.includes(0x22);
  const q = (hasS && !hasD) ? 0x22 : 0x27;
  let out = String.fromCodePoint(q);
  for (const cp of cps) {
    if (cp === q || cp === 0x5c) { out += '\\' + String.fromCodePoint(cp); continue; }
    if (cp === 0x09) { out += '\\t'; continue; }
    if (cp === 0x0a) { out += '\\n'; continue; }
    if (cp === 0x0d) { out += '\\r'; continue; }
    if (!printableFn(cp)) {
      if (cp < 0x100) out += '\\x' + cp.toString(16).padStart(2,'0');
      else if (cp < 0x10000) out += '\\u' + cp.toString(16).padStart(4,'0');
      else out += '\\U' + cp.toString(16).padStart(8,'0');
      continue;
    }
    out += String.fromCodePoint(cp);
  }
  return out + String.fromCodePoint(q);
}
export function runChunk(cps) {
  const s = String.fromCodePoint(...cps);
  const r = spawnSync(EXE, ['--k1', s, '--v1', '1', '--k2', 'zz', '--v2', '2'],
    { encoding: 'utf8', maxBuffer: 64*1024*1024 });
  return r;
}
EOF
