cat > /tmp/us/sweep.mjs <<'EOF'
import { nodeIsPrintable, pyReprBody, runChunk } from './differ.mjs';
const lo = parseInt(process.argv[2],16), hi = parseInt(process.argv[3],16);
const CHUNK = 700;
const mismatches = [];
let tested = 0;
function skip(cp){
  if (cp === 0x00) return true;                 // cannot pass NUL in argv
  if (cp >= 0xD800 && cp <= 0xDFFF) return true; // surrogates: invalid UTF-8 argv
  if (cp === 0x27 || cp === 0x22) return true;   // quote-selection: test separately
  return false;
}
let batch = [];
async function flush(){
  if (!batch.length) return;
  const cps = ['A'.codePointAt(0), ...batch];
  const r = runChunk(cps);
  const line1 = (r.stdout||'').split('\n')[0];
  const expected = 'bidict({' + pyReprBody(cps, nodeIsPrintable) + ": 1, 'zz': 2})";
  if (line1 !== expected) {
    // per-codepoint bisect within the batch
    for (const cp of batch) {
      const one = ['A'.codePointAt(0), cp];
      const rr = runChunk(one);
      const l = (rr.stdout||'').split('\n')[0];
      const exp = 'bidict({' + pyReprBody(one, nodeIsPrintable) + ": 1, 'zz': 2})";
      if (l !== exp) mismatches.push({cp, got:l, exp});
    }
  }
  tested += batch.length;
  batch = [];
}
for (let cp = lo; cp <= hi; cp++) {
  if (skip(cp)) continue;
  batch.push(cp);
  if (batch.length >= CHUNK) await flush();
}
await flush();
console.log(JSON.stringify({range:[process.argv[2],process.argv[3]], tested, nMismatch: mismatches.length,
  mismatches: mismatches.map(m=>({cp:m.cp.toString(16).toUpperCase().padStart(4,'0'), got:m.got, exp:m.exp}))}, null, 1));
EOF
